"use client"
import Link from "next/link"
import { ChevronRight } from "lucide-react"
import { useEffect, useState } from "react"
import { useRouter } from "next/navigation"

export default function AccountPage() {
const router = useRouter()
    const [isMobile, setIsMobile] = useState(true)

    useEffect(() => {
      const handleResize = () => {
        const mobile = window.innerWidth < 768
        setIsMobile(mobile)
        if (!mobile) {
          router.push("/account/dashboard")
        }
      }
      handleResize()
      window.addEventListener("resize", handleResize)
      
      return () => window.removeEventListener("resize", handleResize)
    }, [router])
  
    if (!isMobile) return null
  return (
    <div className="relative max-w-md mx-auto min-h-screen">
   

      {/* Main Content */}
      <div className="">
        <div className="space-y-4">
          {/* Profile Card */}
          <div className="bg-white rounded-xl p-5 border border-[rgba(0,0,0,0.08)]">
  <div className="flex justify-between items-center">
    <div className="flex items-center gap-3">
      <span>
      <svg width="18" height="18" viewBox="0 0 18 18" fill="none" xmlns="http://www.w3.org/2000/svg">
<path d="M9.11992 8.1525C9.04492 8.145 8.95492 8.145 8.87242 8.1525C7.08742 8.0925 5.66992 6.63 5.66992 4.83C5.66992 2.9925 7.15492 1.5 8.99992 1.5C10.8374 1.5 12.3299 2.9925 12.3299 4.83C12.3224 6.63 10.9049 8.0925 9.11992 8.1525Z" stroke="#1E1E1E" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
<path d="M5.36906 10.92C3.55406 12.135 3.55406 14.115 5.36906 15.3225C7.43156 16.7025 10.8141 16.7025 12.8766 15.3225C14.6916 14.1075 14.6916 12.1275 12.8766 10.92C10.8216 9.5475 7.43906 9.5475 5.36906 10.92Z" stroke="#1E1E1E" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
</svg>

      </span>
      <span className="font-ubuntu text-lg font-medium text-[#1E1E1E]">Profile</span>
    </div>
    <span>
    <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
<path d="M-4.37114e-07 10C-1.95827e-07 15.52 4.48 20 10 20C15.52 20 20 15.52 20 10C20 4.48 15.52 -6.78401e-07 10 -4.37114e-07C4.48 -1.95827e-07 -6.78401e-07 4.48 -4.37114e-07 10ZM13 10L9 14L9 6L13 10Z" fill="#030359"/>
</svg>

    </span>
  </div>
</div>

          {[
            { icon: DashboardIcon, text: 'Dashboard', link: '/account/dashboard' },
            { icon: LocationIcon, text: 'Addresses', link: '/account/addresses' },
            { icon: WalletIcon, text: 'Payment Methods', link: '/account/payment-methods' },
            { icon: OrdersIcon, text: 'Orders', link: '/account/orders' },
            { icon: VouchersIcon, text: 'Vouchers', link: '/account/vouchers' },
            { icon: PartpaymentsIcon, text: 'Part Payment', link: '/account/part-payment' },
            { icon: SettingsIcon, text: 'Settings', link: '/account/settings' },
          ].map((item, index) => (
            <Link key={index} href={item.link}>
            <div key={index} className="bg-white rounded-xl p-5 border border-[rgba(0,0,0,0.08)]">
  <div className="flex justify-between items-center">
    <div className="flex items-center gap-3">
      <item.icon />
      <span className="font-ubuntu text-lg font-medium text-[#1E1E1E]">{item.text}</span>
    </div>
    <span>
    <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
<path d="M-4.37114e-07 10C-1.95827e-07 15.52 4.48 20 10 20C15.52 20 20 15.52 20 10C20 4.48 15.52 -6.78401e-07 10 -4.37114e-07C4.48 -1.95827e-07 -6.78401e-07 4.48 -4.37114e-07 10ZM13 10L9 14L9 6L13 10Z" fill="#030359"/>
</svg>

    </span>
  </div>
</div>
</Link>
          ))}

        </div>
      </div>
    </div>
  )
}












